/**
 * Check that the reference of the SDK in `docs/reference/sdk/` matches the code.
 *
 * The reference is generated by TypeDoc from the types and the documentation comments. It is generated again in a
 * temporary folder and compared with the versioned one. TypeDoc also fails when a public export has no comment, so a
 * missing comment fails this check too.
 */

import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, posix } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const REFERENCE = join(ROOT, "docs", "reference", "sdk");

/** The differences between two folders of files. */
export interface TreeDifferences {
  readonly missing: string[];
  readonly unexpected: string[];
  readonly changed: string[];
}

/**
 * Compare the expected files with the files found.
 *
 * @param expected - The generated files, by relative path.
 * @param actual - The versioned files, by relative path.
 */
export function compareTrees(expected: ReadonlyMap<string, string>, actual: ReadonlyMap<string, string>): TreeDifferences {
  return {
    missing: [...expected.keys()].filter((path) => !actual.has(path)).sort(),
    unexpected: [...actual.keys()].filter((path) => !expected.has(path)).sort(),
    changed: [...expected].filter(([path, content]) => actual.has(path) && actual.get(path) !== content).map(([path]) => path).sort(),
  };
}

function readTree(folder: string, prefix = ""): Map<string, string> {
  const files = new Map<string, string>();
  if (!existsSync(folder)) {
    return files;
  }
  for (const entry of readdirSync(folder, { withFileTypes: true })) {
    const relative = posix.join(prefix, entry.name);
    if (entry.isDirectory()) {
      for (const [path, content] of readTree(join(folder, entry.name), relative)) {
        files.set(path, content);
      }
    } else {
      files.set(relative, readFileSync(join(folder, entry.name), "utf8"));
    }
  }
  return files;
}

function main(): number {
  const work = mkdtempSync(join(tmpdir(), "vtherm-reference-"));
  try {
    try {
      execFileSync("node", [join(ROOT, "node_modules", "typedoc", "bin", "typedoc"), "--out", work], { cwd: ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      const output = error instanceof Error && "stderr" in error ? String(error.stderr) + String((error as { stdout?: string }).stdout ?? "") : String(error);
      console.error(`TypeDoc failed. A public export of the SDK probably has no documentation comment:\n${output}`);
      return 1;
    }
    const differences = compareTrees(readTree(work), readTree(REFERENCE));
    if (differences.missing.length + differences.unexpected.length + differences.changed.length > 0) {
      const lines = [
        ...differences.missing.map((path) => `  missing: ${path}`),
        ...differences.unexpected.map((path) => `  no longer generated: ${path}`),
        ...differences.changed.map((path) => `  out of date: ${path}`),
      ];
      console.error(`The reference of the SDK in docs/reference/sdk/ does not match the code. Run 'npm run docs:reference' and commit the result.\n${lines.join("\n")}`);
      return 1;
    }
    console.log("The reference of the SDK is up to date.");
    return 0;
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exit(main());
}
